default.pixel:
(uv, u) => {
  const p = rotate(uv - vec2(0.5, 0.5), u.angle);
  const band = smoothstep(0.5 - u.softness, 0.5 + u.softness, fract(p.x * u.count));
  return mix(color(0.1, 0.1, 0.3), color(0.9, 0.8, 0.4), band);
}

(uv, u) => {
